  write("Temperature setting changed to: %f", gEnvTemperatureSetting);
  // This triggers whenever user changes panel control
}

on start {
  // Write to environment variable (updates panel)
  gEnvStatusIndicator = 1;
  gEnvMessageDisplay = "System Ready";
}
```

Declare timer in variables block, set it with setTimer(), and handle with 'on timer' handler. Timers can be one-shot or periodic.

```c
variables {
  msTimer gTxTimer;
  usTimer gHighResTimer;
}

on start {
  // Set timer for 100ms, fires once
  setTimer(gTxTimer, 100);

  // Set timer for 10 microseconds, repeats
  setTimer(gHighResTimer, 10);
}

on timer gTxTimer {
  write("100ms timer fired");
  output(gTestMessage);
  // Reschedule if needed
  setTimer(gTxTimer, 100);
}

on timer gHighResTimer {
  write("High resolution timer fired");
}
```

Use killTimer() function to stop a running timer. Useful for cleanup or conditional timing.

```c
variables {
  msTimer gTimeoutTimer;
  int gMessageReceived = 0;
}

on start {
  setTimer(gTimeoutTimer, 5000);
  gMessageReceived = 0;
}

on message 0x300 {
  gMessageReceived = 1;
  killTimer(gTimeoutTimer);
  write("Message received, timer stopped");
}

on timer gTimeoutTimer {
  if (!gMessageReceived) {
    write("ERROR: Message timeout!");
  }
}
```

Use enumeration for states, timer callbacks for transitions, and message handlers for events.

```c
variables {
  enum StateType {
    STATE_IDLE = 0,
    STATE_INIT = 1,
    STATE_RUNNING = 2,
    STATE_ERROR = 3
  };

  StateType gCurrentState = STATE_IDLE;
  msTimer gStateTimer;
}

on start {
  gCurrentState = STATE_INIT;
  setTimer(gStateTimer, 500);
}

on timer gStateTimer {
  switch (gCurrentState) {
    case STATE_IDLE:
      write("In IDLE state");
      break;
    case STATE_INIT:
      write("Initializing...");
      gCurrentState = STATE_RUNNING;
      setTimer(gStateTimer, 1000);
      break;
    case STATE_RUNNING:
      write("Running");
      break;
  }
}
```

Set timeout when last message received, reset on new message, trigger action on timeout.

```c
variables {
  msTimer gWatchdogTimer;
  int gMessageCount = 0;
  int gWatchdogTimeout = 1000;  // 1 second
}

on message 0x100 {
  gMessageCount++;
  // Reset watchdog timer on each message
  killTimer(gWatchdogTimer);
  setTimer(gWatchdogTimer, gWatchdogTimeout);
}

on timer gWatchdogTimer {
  write("ERROR: Watchdog timeout! Message lost!");
  write("Last received %d messages", gMessageCount);
  // Implement recovery
}
```

Use bitwise operators: AND (&) to extract, shift (>>, <<) to position bits.

```c
on message 0x100 {
  byte byte0 = this.data[0];

  // Extract bit 0 (LSB)
  byte bit0 = byte0 & 0x01;

  // Extract bit 3
  byte bit3 = (byte0 >> 3) & 0x01;

  // Extract bits 4-7 (upper nibble)
  byte upper_nibble = (byte0 >> 4) & 0x0F;

  write("Bit 0: %d, Bit 3: %d, Upper nibble: 0x%X", 
        bit0, bit3, upper_nibble);
}
```

Use OR (|) to set bits, AND with NOT (&~) to clear bits, XOR (^) to toggle.

```c
message 0x200 txMsg;

on start {
  txMsg.data[0] = 0x00;

  // Set bit 0
  txMsg.data[0] = txMsg.data[0] | 0x01;

  // Set bit 3
  txMsg.data[0] = txMsg.data[0] | 0x08;

  // Clear bit 5
  txMsg.data[0] = txMsg.data[0] & 0xDF;  // 0xDF = ~0x20

  // Toggle bit 2
  txMsg.data[0] = txMsg.data[0] ^ 0x04;

  write("Byte value: 0x%02X", txMsg.data[0]);
  output(txMsg);
}
```

