  dword value = 255;

  // Decimal display
  write("Decimal: %d", value);      // Output: 255

  // Hexadecimal display
  write("Hex: 0x%02X", value);      // Output: 0xFF

  // Binary conversion (manual)
  byte binary = 0xA5;  // 10100101
  write("Binary value: 0x%02X", binary);

