  // Simple ternary operator
  write("Engine status: %s", this > 5000 ? "High" : "Low");

  // Nested ternary for multiple conditions
  char* status = (this < 1000) ? "Idle" : 
                 (this < 3000) ? "Normal" : 
                 (this < 6000) ? "High" : "Critical";
  write("RPM: %s", status);

  // Assign value based on condition
  byte engine_state = (this > 3000) ? 0x01 : 0x00;
}
