Functions encapsulate reusable logic. Define with return type and parameters.

```c
// Function to calculate CRC
int CalculateCRC(byte data[], int length) {
  int crc = 0;
  for (int i = 0; i < length; i++) {
    crc = crc ^ data[i];
  }
  return crc;
}

on message 0x100 {
  int computed_crc = CalculateCRC(this.data, this.dlc);
  byte received_crc = this.data[7];

  if (computed_crc == received_crc) {
    write("CRC OK");
  } else {
    write("CRC ERROR! Expected: 0x%02X, Got: 0x%02X", 
          computed_crc, received_crc);
  }
}
```

Use & symbol to pass by reference for arrays and output parameters.

```c
// Pass by reference with &
void SetBit(byte &value, int bit_pos) {
  value = value | (1 << bit_pos);
}

// Return multiple values via reference
void ExtractBytes(dword combined, byte &high, byte &low) {
  high = (combined >> 8) & 0xFF;
  low = combined & 0xFF;
}

on start {
  byte test_byte = 0x00;
  SetBit(test_byte, 3);
  write("After SetBit: 0x%02X", test_byte);

  dword value = 0x1234;
  byte high, low;
  ExtractBytes(value, high, low);
  write("High: 0x%02X, Low: 0x%02X", high, low);
}
```

Arrays store multiple values of same type. Useful for message buffers.

```c
variables {
  byte gDataBuffer[256];
  dword gMessageQueue[10];
  int gBufferIndex = 0;
}

on message 0x100 {
  // Store message data in buffer
  for (int i = 0; i < this.dlc; i++) {
    gDataBuffer[gBufferIndex++] = this.data[i];
    if (gBufferIndex >= 256) {
      gBufferIndex = 0;  // Wrap around
    }
  }
}

void PrintBuffer(byte buffer[], int size) {
  for (int i = 0; i < size; i++) {
    write("Buffer[%d] = 0x%02X", i, buffer[i]);
  }
}
```

Functions can call themselves with modified parameters for recursive logic.

```c
// Calculate factorial recursively
int Factorial(int n) {
  if (n <= 1) {
    return 1;
  }
  return n * Factorial(n - 1);
}

// Sum array elements recursively
int SumArray(byte arr[], int index, int max) {
  if (index >= max) {
    return 0;
  }
  return arr[index] + SumArray(arr, index + 1, max);
}

on start {
  write("5! = %d", Factorial(5));

  byte values[] = {1, 2, 3, 4, 5};
  write("Sum = %d", SumArray(values, 0, 5));
}
```

