Track sequence numbers and detect missing messages.

```c
variables {
  byte gLastSequence = 0;
  int gMissedMessages = 0;
  msTimer gMissCounterReset;
}

on message 0x700 {
  byte current_seq = this.data[0];
  byte expected_seq = (gLastSequence + 1) & 0xFF;

  if (current_seq != expected_seq) {
    int lost = current_seq - expected_seq;
    if (lost < 0) lost += 256;
    gMissedMessages += lost;
    write("Lost %d messages!", lost);
  }

  gLastSequence = current_seq;
  setTimer(gMissCounterReset, 5000);
}

on timer gMissCounterReset {
  write("Total lost: %d", gMissedMessages);
  gMissedMessages = 0;
}
```

Count, time, and categorize CAN messages for analysis.

```c
variables {
  dword gMessageStats[256];
  dword gLastTimestamp[256];
  int gTotalMessages = 0;
}

on message * {
  int msgId = this.id & 0xFF;
  gMessageStats[msgId]++;
  gTotalMessages++;

  dword current_time = timeStamp();
  dword elapsed = current_time - gLastTimestamp[msgId];
  gLastTimestamp[msgId] = current_time;

  if (gTotalMessages % 100 == 0) {
    write("Total: %d, ID: 0x%03X, Interval: %d ms", 
          gTotalMessages, this.id, elapsed);
  }
}
```

Variable load times require adaptive waiting strategies:

```python
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException

# Strategy 1: Use a generous timeout with explicit wait
wait = WebDriverWait(driver, 30)
try:
    element = wait.until(EC.element_to_be_clickable((By.ID, 'slow-btn')))
    element.click()
except TimeoutException:
    driver.save_screenshot('timeout_error.png')
    raise

# Strategy 2: Wait for any of multiple possible states
def any_of(*conditions):
    def _predicate(driver):
        for condition in conditions:
            try:
                result = condition(driver)
                if result:
                    return result
            except:
                pass
        return False
    return _predicate

# Wait for either success or error message
wait = WebDriverWait(driver, 20)
result = wait.until(any_of(
    EC.visibility_of_element_located((By.CLASS_NAME, 'success')),
    EC.visibility_of_element_located((By.CLASS_NAME, 'error'))
))

# Strategy 3: Exponential backoff polling
import time

def wait_with_backoff(driver, locator, max_attempts=5):
    for attempt in range(max_attempts):
        try:
            return driver.find_element(*locator)
        except:
            time.sleep(2 ** attempt)
    raise TimeoutException('Element not found')

element = wait_with_backoff(driver, (By.ID, 'unreliable-element'))
```

**Key Principle**: Design waits around business logic (what the user expects to see) rather than arbitrary time delays.

Drag and drop can be performed using ActionChains or JavaScript as a fallback.

```python
from selenium.webdriver.common.action_chains import ActionChains
from selenium.webdriver.common.by import By

source = driver.find_element(By.ID, 'drag-item')
target = driver.find_element(By.ID, 'drop-zone')

# Method 1: Native drag_and_drop
actions = ActionChains(driver)
actions.drag_and_drop(source, target).perform()

# Method 2: Click and hold + move + release (more control)
actions = ActionChains(driver)
actions.click_and_hold(source).move_to_element(target).pause(0.5).release(target).perform()

# Method 3: Drag by offset (when target coordinates are known)
actions = ActionChains(driver)
actions.click_and_hold(source).move_by_offset(200, 100).release().perform()

# Method 4: JavaScript fallback (when HTML5 drag-drop doesn't work with ActionChains)
def drag_and_drop_js(driver, source, target):
    script = '''
    var src = arguments[0], tgt = arguments[1];
    var dataTransfer = new DataTransfer();
    var dragStartEvent = new DragEvent('dragstart', {
        bubbles: true, cancelable: true, dataTransfer: dataTransfer
    });
    src.dispatchEvent(dragStartEvent);
    var dropEvent = new DragEvent('drop', {
        bubbles: true, cancelable: true, dataTransfer: dataTransfer
    });
    tgt.dispatchEvent(dropEvent);
    var dragEndEvent = new DragEvent('dragend', {
        bubbles: true, cancelable: true, dataTransfer: dataTransfer
    });
    src.dispatchEvent(dragEndEvent);
    '''
    driver.execute_script(script, source, target)

drag_and_drop_js(driver, source, target)
```

**Note**: HTML5 drag-and-drop implementations often use custom event handling. If ActionChains fails, the JavaScript approach simulates the exact events the application expects.
